"use client";

import { Bookmark, Rocket } from "lucide-react";
import { useNews } from "@/hooks/useNews";
import { Skeleton } from "@/components/ui/skeleton";

export function HeroStartup() {
  const { articles: news, isLoading } = useNews('"Startup" OR "Venture Capital" OR "Aporte"', "Startups", 1);
  const article = news?.[0] || {
    title: "Rodadas de Investimento Batem Recorde",
    description: "Buscando as ultimas noticias para voce. Se demorar, o servico pode estar em manutencao.",
    image: "https://images.unsplash.com/photo-1556761175-4b46a572b786?auto=format&fit=crop&q=80&w=2000",
    category: "STARTUPS",
    source: "FOCUS NEWS",
    url: "#",
    publishedAt: new Date().toISOString()
  };

  if (isLoading && (!news || news.length === 0)) {
    return (
      <article className="group relative overflow-hidden rounded-2xl">
        <div className="relative aspect-[3/1] w-full bg-secondary/50 animate-pulse">
          <div className="absolute bottom-0 left-0 right-0 p-4 lg:p-6">
            <div className="h-4 w-16 bg-muted rounded mb-2"></div>
            <div className="h-10 w-3/4 bg-muted rounded mb-3"></div>
            <div className="h-4 w-1/2 bg-muted rounded"></div>
          </div>
        </div>
      </article>
    );
  }

  return (
    <article 
      className="group relative overflow-hidden rounded-2xl cursor-pointer"
      onClick={() => window.open(article.url, "_blank")}
    >
      <div className="relative aspect-[3/1] w-full">
        <img
          src={article.image || "/news-focus.jpg"}
          alt={article.title}
          className="h-full w-full object-cover transition-transform duration-700 group-hover:scale-105"
          />
        <div className="absolute inset-0 bg-gradient-to-t from-background via-background/70 to-transparent" />

        <div className="absolute left-4 top-4 flex items-center gap-2 lg:left-6 lg:top-6">
          <span className="flex items-center gap-1.5 rounded-lg bg-blue-600 px-4 py-1.5 text-xs font-bold tracking-wider text-white uppercase">
            <Rocket className="h-3.5 w-3.5" />
            {article.category || "DESTAQUE"}
          </span>
          <button 
            onClick={(e) => e.stopPropagation()}
            className="flex items-center gap-1.5 rounded-lg border border-foreground/30 bg-background/30 px-3 py-1.5 text-xs font-medium text-foreground backdrop-blur-sm transition-all duration-300 hover:border-blue-500 hover:text-blue-500"
          >
            <Bookmark className="h-3.5 w-3.5" />
            ARQUIVAR
          </button>
        </div>

        <div className="absolute bottom-0 left-0 right-0 p-4 lg:p-6">
          <span className="mb-2 inline-block text-xs font-bold tracking-[0.2em] text-blue-500 uppercase">
            {article.source}
          </span>
          <h2 className="font-heading text-2xl font-bold leading-tight text-foreground lg:text-4xl xl:text-5xl">
            <span className="text-balance">
              {article.title}
            </span>
          </h2>
          <p className="mt-3 max-w-2xl text-sm leading-relaxed text-muted-foreground lg:text-base line-clamp-2">
            {article.description}
          </p>
        </div>
      </div>
    </article>
  );
}
